def is_plain_rect(inp, r0,r1,c0,c1,col):
    for r in range(r0,r1+1):
        for c in range(c0,c1+1):
            if (r in (r0,r1) or c in (c0,c1)):
                if inp[r][c]!=col: return False
            else:
                if inp[r][c]!=0: return False
    return True

