def solve(inp):
    H, W = len(inp), len(inp[0])
    out = [row[:] for row in inp]
    bxs = find_boxes(inp)
    src = [col for col,(r0,r1,c0,c1) in bxs.items() if not is_plain_rect(inp,r0,r1,c0,c1,col)][0]
    sr0,sr1,sc0,sc1 = bxs[src]
    pat = [row[sc0:sc1+1] for row in inp[sr0:sr1+1]]  # outer shape of source
    phi, pwi = sr1-sr0-1, sc1-sc0-1  # interior dims
    for col,(r0,r1,c0,c1) in bxs.items():
        if col == src: continue
        ih, iw = r1-r0-1, c1-c0-1
        if iw == pwi and ih >= phi-1:
            for i in range(len(pat)):
                for j in range(len(pat[0])):
                    rr, cc = r0+i, c0+j
                    if 0<=rr<H and 0<=cc<W:
                        out[rr][cc] = col if pat[i][j]==col else 0
        else:
            for r in range(r0,r1+1):
                for c in range(c0,c1+1):
                    out[r][c] = 0
    return out

