def solve2(inp):
    H, W = len(inp), len(inp[0])
    out = [row[:] for row in inp]
    bxs = find_boxes(inp)
    src = [col for col,(r0,r1,c0,c1) in bxs.items() if not is_plain_rect(inp,r0,r1,c0,c1,col)][0]
    sr0,sr1,sc0,sc1 = bxs[src]
    pat = [row[sc0:sc1+1] for row in inp[sr0:sr1+1]]
    phi, pwi, ph, pw_ = sr1-sr0-1, sc1-sc0-1, len(pat), len(pat[0])
    for col,(r0,r1,c0,c1) in bxs.items():
        if col == src: continue
        ih, iw = r1-r0-1, c1-c0-1
